  fig('perception', 'Свойства восприятия', F('Фундаментальная ошибка атрибуции', D.matrix({ x: 'Результат', y: 'Чей результат', xl: ['успех', 'неудача'], yl: ['чужой', 'мой'], cells: [{ t: '«Я молодец»', d: 'мои личные качества', c: 'lime' }, { t: '«Так сложилось»', d: 'виновата ситуация', c: 'sand' }, { t: '«Повезло»', d: 'ситуация', c: 'sand' }, { t: '«Сам виноват»', d: 'его личные качества', c: 'rose' }] })),
    F('Четыре свойства восприятия', D.tiles([{ t: 'Избирательность', d: 'выделяем одно по сравнению с другим', c: 'sky' }, { t: 'Стереотипизация', d: 'эмоциональные устойчивые стандартные образы', c: 'amber' }, { t: 'Эффект ореола', d: 'судим по одной характеристике, «ярлык»', c: 'rose' }, { t: 'Атрибуция', d: 'приписываем причины и мотивы', c: 'violet' }], 4)));
