  fig('attitudes', 'Установки', F('Три компонента установки', D.cycle([{ t: 'Эмоциональный', d: 'нравится / не нравится', c: 'rose' }, { t: 'Когнитивный', d: 'убеждения, информация', c: 'sky' }, { t: 'Поведенческий', d: 'склонность действовать', c: 'lime' }], 'Установка')),
    F('Четыре важнейшие установки', D.tree({ t: 'Установки сотрудника' }, [{ t: 'К работе', c: 'lime', kids: ['удовлетворённость', 'вовлечённость'] }, { t: 'К организации', c: 'violet', kids: ['приверженность (лояльность)', 'намерение уйти или остаться'] }]), 'Стресс и «восприятие производительности» — НЕ установки.'));
  fig('attitudes', 'Удовлетворённость и вовлечённость', F('Из чего складывается вовлечённость', D.cycle([{ t: 'Обратная связь', c: 'lime' }, { t: 'Карьера', c: 'sky' }, { t: 'Рабочие процессы', c: 'sand' }, { t: 'Руководитель', c: 'violet' }, { t: 'Знание стратегии', c: 'amber' }, { t: 'Признание заслуг', c: 'rose' }, { t: 'Коллеги', c: 'mint' }], 'Вовлечённость +20% прибыли')),
    F('Удовлетворённость vs вовлечённость', D.compare({ t: 'Удовлетворённость', items: ['эмоциональное состояние', '«работа даёт то, что мне важно»', 'зависит от оплаты, руководства, коллег, условий'] }, { t: 'Вовлечённость', items: ['физическое, эмоциональное, интеллектуальное состояние', '«хочу сделать как можно лучше»', 'нужно: работа увлекает + среда помогает'] })));
  fig('attitudes', 'Приверженность', F('Три типа приверженности', D.tiles([{ k: 'ХОЧУ', t: 'Аффективная', d: 'эмоции, принятие ценностей, идентификация, значимость', c: 'lime' }, { k: 'ДОЛЖЕН', t: 'Нормативная', d: 'не подвести команду, боязнь осуждения', c: 'violet' }, { k: 'ВЫНУЖДЕН', t: 'Континуальная', d: 'комфорт, некуда идти, «золотая клетка»', c: 'amber' }], 3)),
    F('Уйти или остаться', D.matrix({ x: 'Возможность альтернативного трудоустройства', y: 'Удовлетворённость работой', xl: ['низкая', 'высокая'], yl: ['низкая', 'высокая'], cells: [{ t: 'Держится за своё место', c: 'sky' }, { t: 'Супервовлечённые', d: 'остаются, хотя могут уйти', c: 'lime' }, { t: 'Не любит работу, но боится потерять', c: 'amber' }, { t: 'Не любит работу, готов уйти', c: 'rose' }] })),
    F('Приверженность работе и компании (мир / Москва)', D.matrix({ x: 'Приверженность компании', y: 'Приверженность работе', xl: ['низкая', 'высокая'], yl: ['низкая', 'высокая'], cells: [{ t: 'Ориентированные на карьеру', d: '14% / 18%', c: 'sky' }, { t: 'Энтузиасты', d: '43% / 30%', c: 'lime' }, { t: 'Недовольные', d: '35% / 42%', c: 'rose' }, { t: 'Ориентированные на компанию', d: '8% / 10%', c: 'amber' }] }), 'Недовольные не всегда уходят, а довольные не всегда остаются.'));

  /* ───────── 6. Мотивация ───────── */
  fig('motivation', 'Мотивация и мотивирование', F('Мотивация ≠ мотивирование', D.compare({ t: 'Мотивация', items: ['внутренние силы сотрудника', 'видна в усилиях, старании, настойчивости, инициативе', 'есть у человека'] }, { t: 'Мотивирование', items: ['действия руководителя', 'создание условий, при которых хочется хорошо работать', 'совпадение интересов организации и сотрудника'] })));
  fig('motivation', 'Потребность → мотив', F('Механизм мотивации', D.chain([{ t: 'Потребность', d: 'осознанная нужда в благах', c: 'sand' }, { t: 'Мотив + стимул', d: 'внутреннее и внешнее побуждение', c: 'amber' }, { t: 'Цель', d: 'выбранное средство удовлетворения', c: 'violet' }, { t: 'Деятельность', d: 'форма поведения', c: 'sky' }, { t: 'Результат', c: 'lime' }])));
  add('motivation', 'Потребность → мотив', { h: 'Содержательные теории: ЧТО мотивирует', simple: 'Маслоу, Макклелланд и Герцберг отвечают на вопрос «какие потребности движут человеком».',
    fig: [F('Пирамида Маслоу (1954) — 7 уровней, как на слайде', D.pyramid([{ k: '7', t: 'Самоактуализация', d: 'развитие, раскрытие способностей', c: 'lime' }, { k: '6', t: 'Эстетические', d: 'красота, чувственность, впечатления', c: 'rose' }, { k: '5', t: 'Познание', d: 'знать, понимать, изучать новое', c: 'amber' }, { k: '4', t: 'Уважение и признание', d: 'статус, репутация, достижения', c: 'sky' }, { k: '3', t: 'Социальные', d: 'любовь, дружба, принадлежность к группе', c: 'violet' }, { k: '2', t: 'Безопасность', d: 'надёжность, защита, постоянство', c: 'amber' }, { k: '1', t: 'Физиологические', d: 'еда, сон, крыша над головой', c: 'rose' }], { side: true }), 'Пока не удовлетворён нижний уровень, верхние почти не мотивируют.'),
      F('Макклелланд (1940-е): три потребности', D.venn('Потребность во власти', 'Потребность в успехе', 'Потребность в причастности', 'Мотивация')),
      F('Двухфакторная модель Герцберга (1959)', D.compare({ t: 'Гигиенические (внешние)', items: ['заработная плата и блага', 'условия работы', 'отношения с коллегами и начальством', 'степень контроля', '→ убирают НЕДОВОЛЬСТВО, но не мотивируют'] }, { t: 'Мотиваторы (внутренние)', items: ['успех, высокая ответственность', 'признание результатов', 'творческий и профессиональный рост', '→ дают УДОВЛЕТВОРЕНИЕ и мотивацию'] }))],
    body: '<p><b>Маслоу</b>: потребности образуют иерархию — человек поднимается выше, когда удовлетворены нижние уровни. На слайде пирамида из 7 уровней (добавлены познание и эстетика).</p><p><b>Макклелланд</b>: люди различаются по силе трёх приобретённых потребностей — во власти, в успехе (достижении) и в причастности. Руководителю нужна сильная потребность во власти, предпринимателю — в успехе.</p><p><b>Герцберг</b>: удовлетворённость и неудовлетворённость — не две стороны одной шкалы. Хорошая зарплата лишь снимает недовольство; работать лучше заставляют содержание работы, ответственность и признание.</p>' + D.example('Пример из лекции', 'Письмо CEO Альфа-банка в марте 2022: честно о санкциях и рисках, благодарность «лучшей команде в стране». Работает на потребности в безопасности и принадлежности.') });
  add('motivation', 'Содержательные теории', { h: 'Процессуальные теории: КАК возникает мотивация', simple: 'Врум, Адамс и Портер–Лоулер объясняют, как человек «взвешивает» усилия и награду.',
    fig: [F('Теория ожиданий Врума (1964)', D.formula([{ t: 'Усилия → результат', d: '«смогу ли я?»', c: 'sky' }, '×', { t: 'Результат → награда', d: '«дадут ли?»', c: 'violet' }, '×', { t: 'Ценность награды', d: '«нужно ли мне это?»', c: 'amber' }, '=', { t: 'Мотивация', c: 'lime' }]), 'Множители: если хоть один равен нулю, мотивации нет.'),
      F('Теория справедливости Адамса (1963)', D.formula([{ t: 'Мои усилия / моё вознаграждение', c: 'lime' }, '⇄', { t: 'Его усилия / его вознаграждение', c: 'violet' }]), 'Видит несправедливость → снижает усилия, требует больше или уходит.'),
      F('Портер–Лоулер (1968): объединяет предыдущие теории', D.chain([{ t: 'Ценность награды + ожидание', c: 'sand' }, { t: 'Усилия', c: 'amber' }, { t: '+ способности + восприятие роли', c: 'sky' }, { t: 'Результат', c: 'violet' }, { t: 'Внутреннее и внешнее вознаграждение', c: 'rose' }, { t: 'Удовлетворение (если справедливо)', c: 'lime' }]), 'Не удовлетворение ведёт к результату, а результат — к удовлетворению.')],
    body: '<p>Процессуальные теории не перечисляют потребности, а описывают <b>механизм выбора</b> поведения: сколько сил вложить, сравнивая ожидаемую награду, её ценность и справедливость.</p><p><b>Теория обогащения труда</b> (термин Герцберга) — 6 факторов в работе: ответственность за производительность, осознание важности работы, самостоятельность в ресурсах, обратная связь, профессиональный рост, влияние на условия труда. <b>Характеристики работы</b> (Хакмэн и Олдхем) — 5 аспектов: разнообразие, законченность, значимость, самостоятельность, обратная связь.</p>' + D.answer('В вопросе «какую теорию применить к кейсу» называй минимум три: Герцберг (что есть — гигиена, чего нет — мотиваторы), Врум (поверит ли, что получит награду), Адамс (справедливо ли).') });
  fig('motivation', 'Восемь теорий', F('Все 8 теорий: две группы', D.tree({ t: 'Теории мотивации' }, [{ t: 'Содержательные — ЧТО', c: 'lime', kids: ['Маслоу', 'Макклелланд', 'Герцберг', 'обогащение труда', 'характеристики работы (Хакмэн–Олдхем)'] }, { t: 'Процессуальные — КАК', c: 'violet', kids: ['Врум — ожидания', 'Адамс — справедливость', 'Портер–Лоулер — комплексная'] }])));
  fig('motivation', 'Лапыгину', F('Пять типов мотивации', D.tiles([{ t: 'Инструментальный', d: 'труд = заработок', c: 'amber' }, { t: 'Целеориентированный', d: 'продвижение, статус', c: 'violet' }, { t: 'Коллективистский', d: 'уважение коллег', c: 'rose' }, { t: 'Интеллектуальный', d: 'сложная интересная работа', c: 'sky' }, { t: 'Комфортный', d: 'комфортные условия', c: 'mint' }], 5)));
  fig('motivation', 'на практике', F('Управление по целям: каскад', D.tree({ t: 'Цели компании', c: 'ink' }, [{ t: 'Цели подразделения X', c: 'violet', kids: ['цели сотрудника A', 'цели сотрудника B'] }, { t: 'Цели подразделения Y', c: 'sky', kids: ['цели сотрудника C'] }]), 'SMART-цели, сотрудник участвует в их выработке, постоянная обратная связь, чёткий срок.'));

  /* ───────── 7. Поколения ───────── */
  fig('generations', 'Научение и деньги', F('Кривая стимулирования персонала (как на слайде)', D.curve({ pts: [[0, 52], [14, 34], [27, 24], [44, 48], [62, 82], [72, 86], [84, 58], [96, 14]], labels: [{ x: 27, y: 24, t: 'A', dy: 22 }, { x: 70, y: 86, t: 'B' }], vlines: [27, 70], zones: [[0, 27, 'мало — не работает'], [27, 70, 'рост отдачи'], [70, 100, 'перебор — спад']], xlab: 'стимул, C', ylab: 'результат, P' }), 'Максимум эффективности — при оптимальном, а не максимальном стимулировании.'),
    F('Мотивация: что даёт компания', D.compare({ t: 'Материальная', items: ['оклад: постоянная и переменная часть', 'премии: квартальная, годовая', 'долгосрочные бонусы, участие в прибыли'] }, { t: 'Нематериальная', items: ['признание: благодарности, доски почёта, персональное', 'программы благополучия (well-being)', 'карьера, обучение, конференции, гибкий график, культура'] })));
  fig('generations', 'Теория поколений', F('Шкала поколений', D.spectrum([{ t: 'Молчаливое', d: '1928–45 · правила', bg: '#d9d2c3' }, { t: 'Бэби-бумеры', d: '1946–64 · самореализация', bg: '#f2c9a0' }, { t: 'X', d: '1964–84 · статус, стабильность', bg: '#f6b48a' }, { t: 'Y', d: '1985–2000 · быстрый рост', bg: '#f39bb4' }, { t: 'Z', d: '2000–10 · быть счастливым', bg: '#c3b5f5' }, { t: 'Альфа', d: '2010–25 · ИИ с рождения', bg: '#a9dbe9' }])));

  /* ───────── 8. Группы ───────── */
  fig('groups', 'Группа и её виды', F('Классификации групп', D.tiles([{ t: 'Малые / большие', d: 'все знают друг друга?', c: 'sky' }, { t: 'Первичные / вторичные', d: 'эмоции или расчёт', c: 'rose' }, { t: 'Ин-группа / аут-группа', d: '«мы» и «они»', c: 'violet' }, { t: 'Референтные', d: 'стандарт и источник норм', c: 'amber' }, { t: 'Формальные / неформальные', d: 'создаёт руководство или спонтанно', c: 'lime' }], 5)),
    F('Группа — мостик', D.chain([{ t: 'Человек', c: 'lime' }, { t: 'Группа', d: 'социализация: нормы, ценности, «как тут всё устроено»', c: 'violet' }, { t: 'Организация', c: 'sky' }], { op: '⇄' })));
  fig('groups', 'Неформальная группа', F('Сделка с группой', D.compare({ t: 'Выгоды', items: ['решить личные проблемы', 'поддержка в трудностях', 'престиж и авторитет', 'принадлежность'] }, { t: 'Цена', items: ['делать то, что нужно группе', 'меньше личной свободы', 'обязательства перед другими', 'свободное время'] }, '⇄')),
    F('Неформальные нормы', D.tiles([{ t: 'Не выделяйся', c: 'sand' }, { t: 'Не проявляй излишнего рвения', c: 'amber' }, { t: 'Не жалуйся начальству', c: 'rose' }], 3)));
  fig('groups', 'Сплочённость', F('Сплочённость × нормы = производительность', D.matrix({ x: 'Сплочённость', y: 'Нормы эффективности', xl: ['низкая', 'высокая'], yl: ['слабые', 'сильные'], cells: [{ t: 'Средняя', c: 'sky' }, { t: 'Высокая', c: 'lime' }, { t: 'Средняя / низкая', c: 'sand' }, { t: 'Низкая', d: 'сплочены против работы', c: 'rose' }], hi: 1 })));
  fig('groups', 'Групповое принятие', F('Решать вместе: весы', D.compare({ t: 'Плюсы', items: ['больше информации и знаний', 'разнообразие точек зрения', 'решения охотнее выполняются (buy-in)'] }, { t: 'Минусы', items: ['временные затраты', 'огруппленное мышление — консенсус любой ценой', 'групповой сдвиг — риск выше, чем у каждого'] })),
    F('Как возникает групповой сдвиг', D.chain([{ t: 'Обсуждение', c: 'sand' }, { t: 'Групповая поляризация', c: 'amber' }, { t: 'Влиятельны самые рискованные', c: 'rose' }, { t: 'Решение радикальнее, чем у каждого', c: 'violet' }])));
  fig('groups', 'Эффекты групповой', F('Фасилитация или лень?', D.compare({ t: 'Вклад ОЦЕНИВАЕТСЯ', items: ['боязнь оценки', '→ социальная фасилитация', 'привычное делаем лучше при других'] }, { t: 'Вклад НЕ оценивается', items: ['анонимность', '→ социальная лень, диффузия ответственности', '«безбилетник»'] })));

