  fig('teams', 'Как группа становится', F('Кривая Катценбаха и Смита', D.curve({ pts: [[4, 50], [22, 16], [44, 50], [66, 80], [92, 94]], labels: [{ x: 4, y: 50, t: 'Рабочая группа', a: 'start', dx: 8 }, { x: 22, y: 16, t: 'Псевдокоманда', dy: 24 }, { x: 44, y: 50, t: 'Потенциальная команда', a: 'start', dx: 8, dy: 4 }, { x: 66, y: 80, t: 'Реальная команда', a: 'end', dx: -8 }, { x: 92, y: 94, t: 'Высокопродуктивная', a: 'end', dx: -4, dy: 30 }], xlab: 'командная эффективность', ylab: 'влияние на результат' }), 'Псевдокоманда работает ХУЖЕ обычной рабочей группы.'),
    F('Модель Такмана', D.curve({ pts: [[0, 40], [14, 46], [32, 20], [58, 58], [80, 82], [100, 86]], labels: [{ x: 14, y: 46, t: 'Forming' }, { x: 32, y: 20, t: 'Storming', dy: 22 }, { x: 58, y: 58, t: 'Norming', a: 'end', dx: -6 }, { x: 88, y: 84, t: 'Performing', a: 'end' }], zones: [[0, 22, 'рабочая группа'], [22, 45, 'псевдокоманда'], [45, 70, 'потенциальная'], [70, 100, 'эффективная']], xlab: 'время', ylab: 'производительность' })));
  fig('teams', 'Условия эффективности', F('Модель GRPI', D.pyramid([{ k: 'G', t: 'Goals — цели', d: 'ясные результаты и приоритеты', c: 'lime' }, { k: 'R', t: 'Roles — роли', d: 'круг обязанностей, принятие лидера', c: 'sky' }, { k: 'P', t: 'Procedures — процессы', d: 'как принимаем решения', c: 'violet' }, { k: 'I', t: 'Interpersonal — отношения', d: 'взаимодействие и гибкость', c: 'amber' }], { side: true })),
    F('Модель 7T', D.cycle([{ t: 'Thrust', d: 'общая цель', c: 'rose' }, { t: 'Trust', d: 'доверие', c: 'sky' }, { t: 'Talent', d: 'знания', c: 'sand' }, { t: 'Teaming skills', d: 'работа сообща', c: 'violet' }, { t: 'Task skills', d: 'выполнение задачи', c: 'amber' }], 'внутренние 5T'), 'Внешний круг: Team leader fit — совместимость с лидером, Team support from the organization — поддержка организации.'),
    F('Ленсиони: 5 пороков команды', D.pyramid([{ k: '5', t: 'Безразличие к результату', d: 'карьеризм и эгоизм', c: 'rose' }, { k: '4', t: 'Нетребовательность к другим', d: 'низкие стандарты', c: 'rose' }, { k: '3', t: 'Необязательность', d: 'неопределённость', c: 'amber' }, { k: '2', t: 'Уход от конфликтов', d: 'молчаливое согласие', c: 'amber' }, { k: '1', t: 'Отсутствие доверия', d: 'страх показать уязвимость', c: 'violet' }], { side: true }), 'Фундамент — доверие: без него рушится всё выше.'),
    F('Лафасто и Ларсон', D.steps([{ t: 'Участники', d: 'нужные навыки' }, { t: 'Отношения', d: 'здоровые связи' }, { t: 'Решение проблем', d: 'вместе' }, { t: 'Руководство', d: 'правильный подход' }, { t: 'Организация', d: 'процессы и культура' }])));
